  "help.chitMaxLoss": "तुमच्या उत्पन्नांतल्यान, म्हयन्याळीं देय, उक्ते रिण, मुजतवाड जाल्लें बिल, आनी बचतींतल्यान चडांत चड लुकसाण सुचयतात — थारावीक % न्हय. बेगीन घेवप चड करून ताचे परस चड आसता; उपरांतच्या म्हयन्यांनी चड करून उणो खर्च येता.",
  "help.loanExtraTiming": "येवपी म्हयने दाखयता: जेन्ना हेर बिलां हळुवार आसतात म्हणजे तुमी ह्या रिणाचेर अतिरिक्त फारीक करूंक शकतात, आनी जड म्हयने जेन्ना तुमी उण्यांत उण्या प्रमाणांत चिकटून रावपाक जाय.",
  "help.incomeEntryBasis": "कर, PF, आनी थारावीक कपात उपरांत तुमच्या बँकेंत कितें उडयता तें टेक-होम जुळटा — दबाव आनी मुक्त-रोख गणिताक सगळ्यांत बरें. तुमी घालतात तो दरेक क्रमांक कर पयलीं आसत जाल्यारूच ग्रॉस उपेगी पडटा; फुकट रोख तुमच्या प्रत्यक्ष बँक शिल्लका परस उणी दिसूं येता, जर टेक-होम येणावळ स्थूल परस उणी आसल्यार.",
