  "profileHub.scoreWhy.pressure.high": "उत्पन्नाच्या सापेक्ष जायतीं बिलां बेगीन वा मुजतवाडाचीं आसतात.",
  "profileHub.scoreWhy.pressure.mid": "उत्पन्नाचो लक्षांत येवपी वाटो परत परत येवपी देयांनी वता.",
  "profileHub.scoreWhy.pressure.low": "सध्या येणावळीच्या सापेक्ष बिलां वेवस्थापन करपाक मेळटात.",
  "profileHub.scoreWhy.health.what": "बिल भार, फारीकणी संवय, बचत बफर, आनी रिणाचो ट्रेंड एकठांय करता.",
  "profileHub.scoreWhy.health.low": "भार, बफर वा फारीकणी सुसंगतींत दुबळेपण हें सकयल ओडटा.",
  "profileHub.scoreWhy.health.mid": "कांय वाठारांनी घट्ट — कांय संवय वा बफर हें उखलूंक शकतले.",
  "profileHub.scoreWhy.health.good": "एकंदरीत संवय आनी बफर भलायकेक बरो दिसतात.",
  "profileHub.scoreWhy.runway.what": "म्हयने तुमी उत्पन्न थांबल्यार गरजेच्या वस्तूंक कव्हर करूंक शकतले (द्रव बचत + फुकट रोख).",
  "profileHub.scoreWhy.runway.critical": "खूप पातळ कुशन — एक उत्पन्नाचो धक्को सोंसप कठीण जातलें.",
  "profileHub.scoreWhy.runway.thin": "सोयीस्कर ३-६ म्हयन्यांच्या राखीवाच्या सकयल.",
  "profileHub.scoreWhy.runway.ok": "धांवपट्टी सध्या खातीर सुरक्षीत रेंजांत आसा.",
  "profileHub.scoreWhy.flexibility.what": "म्हयन्याळ्या थारावीक देयांनी तुमकां कितली सुवात आसा.",
  "profileHub.scoreWhy.flexibility.low": "चडशी येणावळ पयलींच परत परत येवपी बिलां खातीर वचनबद्ध आसता.",
  "profileHub.scoreWhy.flexibility.ok": "तुमी दर म्हयन्याक अर्थपूर्ण फुकट रोख रक्कम दवरतात.",
  "profileHub.scoreWhy.debt.what": "EMI आनी म्हयन्याळ्या उत्पन्नाचो वाटो म्हूण रीण फारीक करप.",
  "profileHub.scoreWhy.debt.high": "EMI भार जड आसा — नव्या रिणांक लागून रोख प्रवाहाचेर ताण पडटलो.",
  "profileHub.scoreWhy.debt.ok": "रिणाचें फारीकपण वेवस्थापन करपाक येवपी बँडा भितर आसता.",
  "profileHub.scoreWhy.lending.what": "तुमी रिणां दितना दिल्ल्या वा मेळिल्ल्या वेळार परतफेड करपाचो मागो घेता.",
  "profileHub.scoreWhy.lending.empty": "अजून रिणाची नोंद ना — हो गूण तयार करपाक डील जोडात आनी परतफेड लॉग करात.",
  "profileHub.scoreWhy.lending.low": "उशीरा वा आंशिक परतफेड केल्ल्यान विस्वास उणो जालो.",
  "profileHub.scoreWhy.lending.ok": "परतफेडीचो इतिहास विस्वासांत घेवपासारको दिसता.",
  "profileHub.scoreFix.pressure.clearOverdue": "पयलीं ओव्हरड्यू बिलां निवळ करात — तांणी ह्या गूणाक चड दुखयतात.",
  "profileHub.scoreFix.pressure.trimSubscriptions": "सदस्यताय आनी पर्यायी EMI पुनरावलोकन करात तुमी थांबवंक शकतात.",
  "profileHub.scoreFix.pressure.payOnTime": "दबाव स्थीर करपा खातीर ह्या म्हयन्यांत नियत तारखां पयलीं फारीक करचें.",
  "profileHub.scoreFix.runway.buildReserve": "दर पगार दिसा द्रव बचतींत थारावीक रक्कम व्हरची.",
  "profileHub.scoreFix.runway.reduceBurn": "धांवपट्टी वाडोवपा खातीर गरजे भायर परत परत येवपी बिलां ट्रिम करप.",
  "profileHub.scoreFix.health.reduceBurden": "उच्च भार आशिल्लीं वचनबद्धताय उणी करप वा परतून वेळापत्रक करप.",
  "profileHub.scoreFix.health.buildBuffer": "द्रव बचतींत 3-6 म्हयने खर्च लक्ष्य करप.",
  "profileHub.scoreFix.health.payOnTime": "फारीकणीची वळख दवरात — दरेक बिल फारीकणी लॉग करात.",
  "profileHub.scoreFix.health.reduceDebt": "पयलीं चड व्याजाच्या शिल्लकांचेर चिप पयस करात.",
  "profileHub.scoreFix.health.keepGoing": "Keep current habits — you're on track.",
  "profileHub.scoreFix.health.general": "उत्पन्न, बिलां, आनी बचत लॉग करात म्हणजे गूण अचूक उरतात.",
  "profileHub.scoreFix.flexibility.reduceBurden": "परत परत येवपी देय उणे करात वा शक्य आसल्यार EMI वाटाघाटी करात.",
  "profileHub.scoreFix.flexibility.trackSpend": "लॉग व्हेरिएबल खर्च म्हणून फुकट रोख वास्तव जुळटा.",
  "profileHub.scoreFix.debt.attackHighInterest": "पगाराच्या क्रमांत क्रेडीट कार्ड आनी उच्च दराच्या रिणांक प्राधान्य दिवप.",
  "profileHub.scoreFix.debt.avoidNewEmi": "ओव्हरलोड येणावळीच्या ~35% सकयल देंवता मेरेन नवे EMI टाळचे.",
  "profileHub.scoreFix.lending.onTime": "कबूल केल्ल्या तारखेक रिणाचे हप्ते एकठांय करप वा फारीक करप.",
  "profileHub.scoreFix.lending.addDeals": "ट्रस्ट ट्रॅक करपाक सुरवात करपाक रिणां दिवपाच्या पानांतल्यान रिणां दिवपाची नोंद जोडची.",
