  "wealthDetail.property.narrative.valueVsIncome": "ही मालमत्ता ~{multiple}× कागदाचेर तुमची वर्सुकी उत्पन्न — एक व्हडली एकाग्रताय; आणीबाणी आनी विविधताय नियोजनांत तें घटक.",
  "wealthDetail.property.narrative.highValueTier3Liquidity": "ल्हान शारांतल्या ह्या मोलाचेर, खरेदीदार सोदपाक म्हयने लागूं येतात — वास्तवीक रितीन किंमत आनी पुराय मोल क्षणार्धांत मेळपी रोख म्हणून मेजप टाळचें.",
  "wealthDetail.property.narrative.highValueTier2Liquidity": "टायअर-2 बाजारपेठे खातीर उच्च तिकीट — तुमच्या सांगिल्ल्या मोलाचेर बेगीन तरलताय गृहीत धरचे पयलीं लागसार हालींच नोंदणीकृत विक्री तपासात.",
  "wealthDetail.property.narrative.targetCagrReality": "हांगाच्यान 12% CAGR फाटल्यान धांवपाक आयच्या गतींत ~{years} चड वर्सां लागतलीं — तुमच्या होल्डिंगान पयलींच बळिश्ट नाममात्र फायदो दिलो; फुडाराचें परतावो सामान्य जावंक शकता.",
  "wealthDetail.property.narrative.landHold": "जमीन: सगळ्यांत उणी देखरेख पूण सगळ्यांत मंद तरलताय — 10+ वर्सांच्या क्षितीजाक सगळ्यांत बरें; वळेरी करचे पयलीं भार, विभागणी, आनी रस्तो-रुंद करपाच्यो अधिसुचोवण्यो तपासात.",
  "wealthDetail.property.narrative.commercialHold": "वेवसायीक: रिक्त सुवात आनी भाड्याचो दर्जो थळा इतलोच म्हत्वाचो — फुटफॉल वा भाडें अटी दुबळीं जाल्यार परतून मोलावप.",
  "wealthDetail.property.narrative.residentialHold": "निवासी: स्वताचो वापर केल्ल्यान विकपाचो दबाव उणो जाता; भाड्यान घेतल्यार भाड्याच्या उलाढालीचो आनी समाजाची देखरेख वाडोवपाचो मागोवपाक.",
  "wealthDetail.property.narrative.verifyTitle": "खंयचेय विक्री पयलीं: भार प्रमाणपत्र, मालमत्ता कर पावती, आनी उत्परिवर्तन स्थिती — हांगा कळाव कागदी फायदो मिटयता.",
